"""
One-Step Local Folder Updater for TradePilot NSE (Telegram EOD Alerts Patch).
Place this file inside your existing local `TradePilot_NSE` folder and run:
    python apply_telegram_update.py
It updates only the 5 changed files in-place without touching your `venv/` or `data_store/tradepilot_nse.db`.
"""
import json
from pathlib import Path

PATCH_FILES = json.loads("{\"utils/telegram_notifier.py\": \"\\\"\\\"\\\"\\nTelegram Notification Module for TradePilot NSE.\\nFormats and dispatches daily End-of-Day BUY WATCH and top-ranked stock alerts to a user's Telegram chat\\nvia the official Telegram Bot HTTP API (`https://api.telegram.org/bot<TOKEN>/sendMessage`).\\nUses Python's built-in `urllib.request` so zero extra third-party dependencies are required.\\n\\\"\\\"\\\"\\nimport json\\nimport os\\nimport urllib.request\\nimport urllib.error\\nfrom typing import Any, Dict, List, Optional\\nimport pandas as pd\\n\\nfrom config import DISCLAIMER_TEXT\\nfrom utils.logging_config import get_logger\\nfrom utils.helpers import format_inr, format_pct, now_ist\\n\\nlogger = get_logger(\\\"telegram_notifier\\\")\\n\\n\\ndef resolve_telegram_credentials(db=None, bot_token: Optional[str] = None, chat_id: Optional[str] = None) -> Dict[str, Any]:\\n    \\\"\\\"\\\"\\n    Resolves Telegram Bot Token, Chat ID, and enabled status from:\\n    1. Explicit function arguments\\n    2. Environment variables (`TRADEPILOT_TELEGRAM_BOT_TOKEN`, `TRADEPILOT_TELEGRAM_CHAT_ID`)\\n    3. SQLite `user_settings` table (`telegram_config`)\\n    \\\"\\\"\\\"\\n    env_token = os.getenv(\\\"TRADEPILOT_TELEGRAM_BOT_TOKEN\\\", \\\"\\\").strip()\\n    env_chat = os.getenv(\\\"TRADEPILOT_TELEGRAM_CHAT_ID\\\", \\\"\\\").strip()\\n\\n    db_cfg = {}\\n    if db is not None:\\n        db_cfg = db.get_setting(\\\"telegram_config\\\", {}) or {}\\n\\n    final_token = (bot_token or env_token or db_cfg.get(\\\"bot_token\\\", \\\"\\\")).strip()\\n    final_chat_id = (chat_id or env_chat or db_cfg.get(\\\"chat_id\\\", \\\"\\\")).strip()\\n    enabled = bool(db_cfg.get(\\\"enabled\\\", True))\\n    max_alerts = int(db_cfg.get(\\\"max_alerts\\\", 5))\\n    include_hold_if_empty = bool(db_cfg.get(\\\"include_hold_if_empty\\\", True))\\n\\n    return {\\n        \\\"bot_token\\\": final_token,\\n        \\\"chat_id\\\": final_chat_id,\\n        \\\"enabled\\\": enabled,\\n        \\\"max_alerts\\\": max_alerts,\\n        \\\"include_hold_if_empty\\\": include_hold_if_empty,\\n    }\\n\\n\\ndef format_eod_telegram_message(\\n    screening_df: pd.DataFrame,\\n    sync_summary: Optional[Dict[str, Any]] = None,\\n    max_alerts: int = 5,\\n    include_hold_if_empty: bool = True,\\n) -> str:\\n    \\\"\\\"\\\"\\n    Builds an HTML-formatted Telegram summary message highlighting the market breadth and top BUY WATCH setups.\\n    \\\"\\\"\\\"\\n    date_str = now_ist().strftime(\\\"%d %b %Y (%H:%M IST)\\\")\\n\\n    if screening_df is None or screening_df.empty:\\n        return (\\n            f\\\"<b>\\ud83d\\udcca TradePilot NSE \\u2014 EOD Alert ({date_str})</b>\\\\n\\\\n\\\"\\n            f\\\"\\u26a0\\ufe0f No screening records available in database. Please run Smart Sync.\\\"\\n        )\\n\\n    total_scanned = len(screening_df)\\n    buy_df = screening_df[screening_df[\\\"signal\\\"] == \\\"BUY WATCH\\\"].sort_values(\\\"overall_score\\\", ascending=False)\\n    hold_df = screening_df[screening_df[\\\"signal\\\"] == \\\"HOLD WATCH\\\"].sort_values(\\\"overall_score\\\", ascending=False)\\n    avoid_count = int((screening_df[\\\"signal\\\"] == \\\"AVOID\\\").sum())\\n    latest_trade_date = str(screening_df[\\\"trade_date\\\"].max())\\n\\n    lines: List[str] = [\\n        f\\\"<b>\\ud83d\\udcc8 TradePilot NSE \\u2014 Daily EOD Report</b>\\\",\\n        f\\\"<b>Bar Date:</b> <code>{latest_trade_date}</code> | <b>Generated:</b> {date_str}\\\",\\n        f\\\"<b>Universe Breadth:</b> Scanned: <b>{total_scanned}</b> | \\ud83d\\udfe2 BUY WATCH: <b>{len(buy_df)}</b> | \\ud83d\\udfe1 HOLD WATCH: <b>{len(hold_df)}</b> | \\ud83d\\udd34 AVOID: <b>{avoid_count}</b>\\\",\\n        \\\"\\\",\\n    ]\\n\\n    if not buy_df.empty:\\n        lines.append(f\\\"<b>\\ud83d\\ude80 Top {min(len(buy_df), max_alerts)} BUY WATCH Setups:</b>\\\")\\n        lines.append(\\\"\\\")\\n        for rank, (_, row) in enumerate(buy_df.head(max_alerts).iterrows(), start=1):\\n            sym = row[\\\"symbol\\\"]\\n            close = format_inr(row[\\\"close_price\\\"])\\n            pct = format_pct(row[\\\"daily_pct_change\\\"])\\n            score = f\\\"{row['overall_score']:.1f}/100\\\"\\n            entry_z = f\\\"\\u20b9{row['entry_low']:,.2f}\\u2013\\u20b9{row['entry_high']:,.2f}\\\"\\n            sl = f\\\"\\u20b9{row['stop_loss']:,.2f} (-{row['downside_pct']:.1f}%)\\\"\\n            t1 = f\\\"\\u20b9{row['target_1']:,.2f}\\\"\\n            t2 = f\\\"\\u20b9{row['target_2']:,.2f} (+{row['upside_pct']:.1f}%)\\\"\\n            rr = f\\\"1:{row['risk_reward_ratio']:.2f}\\\"\\n            strat = row.get(\\\"matched_strategies\\\", \\\"N/A\\\")\\n\\n            lines.append(\\n                f\\\"<b>{rank}. #{sym}</b> \\u2014 {close} ({pct}) | <b>Score: {score}</b>\\\\n\\\"\\n                f\\\"   \\u2022 <b>Strategy:</b> {strat}\\\\n\\\"\\n                f\\\"   \\u2022 <b>Entry Zone:</b> <code>{entry_z}</code>\\\\n\\\"\\n                f\\\"   \\u2022 <b>Stop-Loss:</b> <code>{sl}</code>\\\\n\\\"\\n                f\\\"   \\u2022 <b>Targets:</b> T1 <code>{t1}</code> | T2 <code>{t2}</code> (<b>R:R {rr}</b>)\\\"\\n            )\\n            lines.append(\\\"\\\")\\n    else:\\n        lines.append(\\\"\\u2139\\ufe0f <b>No stocks met strict BUY WATCH criteria today.</b>\\\")\\n        if include_hold_if_empty and not hold_df.empty:\\n            lines.append(\\\"\\\")\\n            lines.append(f\\\"<b>\\ud83d\\udc40 Top {min(len(hold_df), 3)} HOLD WATCH Candidates to Monitor:</b>\\\")\\n            for rank, (_, row) in enumerate(hold_df.head(3).iterrows(), start=1):\\n                lines.append(\\n                    f\\\"<b>{rank}. #{row['symbol']}</b> \\u2014 \\u20b9{row['close_price']:,.2f} ({format_pct(row['daily_pct_change'])}) | \\\"\\n                    f\\\"Score: <b>{row['overall_score']:.1f}</b> | Entry: <code>\\u20b9{row['entry_low']:,.2f}\\u2013\\u20b9{row['entry_high']:,.2f}</code> | \\\"\\n                    f\\\"SL: <code>\\u20b9{row['stop_loss']:,.2f}</code> | T2: <code>\\u20b9{row['target_2']:,.2f}</code>\\\"\\n                )\\n            lines.append(\\\"\\\")\\n\\n    if sync_summary:\\n        lines.append(f\\\"<i>Sync Status: {sync_summary.get('details', 'Completed')}</i>\\\")\\n\\n    lines.append(\\\"<i>\\u26a0\\ufe0f Analytical estimates only; not investment advice or assured execution prices.</i>\\\")\\n    return \\\"\\\\n\\\".join(lines)\\n\\n\\ndef send_telegram_message(\\n    message_html: str,\\n    bot_token: str,\\n    chat_id: str,\\n    timeout_sec: int = 15,\\n) -> Dict[str, Any]:\\n    \\\"\\\"\\\"\\n    Sends an HTML-formatted message via the Telegram Bot API.\\n    Returns {'ok': True/False, 'status_code': ..., 'description': ...}.\\n    \\\"\\\"\\\"\\n    if not bot_token or not chat_id:\\n        return {\\n            \\\"ok\\\": False,\\n            \\\"error\\\": \\\"Missing Telegram Bot Token or Chat ID. Configure them in .env or Custom Settings -> Telegram Alerts.\\\",\\n        }\\n\\n    url = f\\\"https://api.telegram.org/bot{bot_token.strip()}/sendMessage\\\"\\n    payload = {\\n        \\\"chat_id\\\": str(chat_id).strip(),\\n        \\\"text\\\": message_html,\\n        \\\"parse_mode\\\": \\\"HTML\\\",\\n        \\\"disable_web_page_preview\\\": True,\\n    }\\n    data_bytes = json.dumps(payload).encode(\\\"utf-8\\\")\\n    req = urllib.request.Request(url, data=data_bytes, headers={\\\"Content-Type\\\": \\\"application/json\\\"}, method=\\\"POST\\\")\\n\\n    try:\\n        with urllib.request.urlopen(req, timeout=timeout_sec) as resp:\\n            resp_body = resp.read().decode(\\\"utf-8\\\")\\n            parsed = json.loads(resp_body)\\n            if parsed.get(\\\"ok\\\"):\\n                logger.info(f\\\"Telegram alert dispatched successfully to chat_id={chat_id}\\\")\\n                return {\\\"ok\\\": True, \\\"result\\\": parsed.get(\\\"result\\\")}\\n            else:\\n                err_desc = parsed.get(\\\"description\\\", \\\"Unknown Telegram API error\\\")\\n                logger.error(f\\\"Telegram API rejected message: {err_desc}\\\")\\n                return {\\\"ok\\\": False, \\\"error\\\": err_desc}\\n    except urllib.error.HTTPError as http_err:\\n        try:\\n            err_body = http_err.read().decode(\\\"utf-8\\\")\\n            err_json = json.loads(err_body)\\n            desc = err_json.get(\\\"description\\\", str(http_err))\\n        except Exception:\\n            desc = str(http_err)\\n        logger.error(f\\\"Telegram HTTP error ({http_err.code}): {desc}\\\")\\n        return {\\\"ok\\\": False, \\\"error\\\": f\\\"HTTP {http_err.code}: {desc}\\\"}\\n    except Exception as exc:\\n        logger.error(f\\\"Failed to send Telegram alert: {exc}\\\")\\n        return {\\\"ok\\\": False, \\\"error\\\": str(exc)}\\n\\n\\ndef dispatch_eod_telegram_alert(db, sync_summary: Optional[Dict[str, Any]] = None, force_send: bool = False) -> Dict[str, Any]:\\n    \\\"\\\"\\\"\\n    High-level helper called by `eod_auto_update.py` or the Streamlit UI to format and send the latest EOD BUY WATCH alert.\\n    \\\"\\\"\\\"\\n    cfg = resolve_telegram_credentials(db)\\n    if not cfg[\\\"enabled\\\"] and not force_send:\\n        logger.info(\\\"Telegram alerts are disabled in settings; skipping notification.\\\")\\n        return {\\\"ok\\\": False, \\\"skipped\\\": True, \\\"reason\\\": \\\"Telegram alerts disabled in settings.\\\"}\\n\\n    if not cfg[\\\"bot_token\\\"] or not cfg[\\\"chat_id\\\"]:\\n        logger.info(\\\"Telegram credentials not configured yet; skipping EOD Telegram notification.\\\")\\n        return {\\n            \\\"ok\\\": False,\\n            \\\"skipped\\\": True,\\n            \\\"reason\\\": \\\"Telegram Bot Token or Chat ID not configured.\\\",\\n        }\\n\\n    df = db.get_all_screening_results()\\n    msg_html = format_eod_telegram_message(\\n        screening_df=df,\\n        sync_summary=sync_summary,\\n        max_alerts=cfg[\\\"max_alerts\\\"],\\n        include_hold_if_empty=cfg[\\\"include_hold_if_empty\\\"],\\n    )\\n    return send_telegram_message(\\n        message_html=msg_html,\\n        bot_token=cfg[\\\"bot_token\\\"],\\n        chat_id=cfg[\\\"chat_id\\\"],\\n    )\\n\", \"eod_auto_update.py\": \"\\\"\\\"\\\"\\nAutomated End-of-Day Update, Daily Screening & Telegram Alert Runner for TradePilot NSE.\\nCan be executed from the command line or scheduled via Windows Task Scheduler at 16:15 IST every weekday:\\n    python eod_auto_update.py\\nAlso exports the daily BUY WATCH and full screening report to `exports/` and dispatches Telegram BUY WATCH alerts.\\n\\\"\\\"\\\"\\nimport argparse\\nfrom pathlib import Path\\nfrom config import EXPORTS_DIR\\nfrom data.database import DatabaseManager\\nfrom data.market_data import MarketDataService\\nfrom analysis.pipeline import run_full_screening_pipeline\\nfrom utils.telegram_notifier import dispatch_eod_telegram_alert\\nfrom utils.logging_config import get_logger\\nfrom utils.helpers import now_ist\\n\\nlogger = get_logger(\\\"eod_automation\\\")\\n\\n\\ndef run_eod_job(force_refresh: bool = False, send_telegram: bool = True) -> dict:\\n    logger.info(\\\"Starting TradePilot NSE End-of-Day automated sync & screening job...\\\")\\n    db = DatabaseManager()\\n    service = MarketDataService(db)\\n\\n    sync_res = service.refresh_stock_universe(force=force_refresh, fetch_fundamentals=True)\\n    logger.info(f\\\"Market data sync finished: {sync_res['details']}\\\")\\n\\n    pipe_res = run_full_screening_pipeline(db)\\n    logger.info(f\\\"Screening pipeline finished: Processed={pipe_res['processed']}, Skipped={pipe_res['skipped']}\\\")\\n\\n    df = db.get_all_screening_results()\\n    csv_path = None\\n    if not df.empty:\\n        date_tag = now_ist().strftime(\\\"%Y%m%d\\\")\\n        csv_path = Path(EXPORTS_DIR) / f\\\"TradePilot_NSE_EOD_{date_tag}.csv\\\"\\n        xlsx_path = Path(EXPORTS_DIR) / f\\\"TradePilot_NSE_EOD_{date_tag}.xlsx\\\"\\n        df.to_csv(csv_path, index=False)\\n        try:\\n            df.to_excel(xlsx_path, index=False, engine=\\\"openpyxl\\\")\\n        except Exception as exc:\\n            logger.warning(f\\\"Excel export skipped: {exc}\\\")\\n        logger.info(f\\\"Saved EOD screening exports to {csv_path}\\\")\\n\\n    tg_res = {\\\"ok\\\": False, \\\"skipped\\\": True}\\n    if send_telegram:\\n        tg_res = dispatch_eod_telegram_alert(db, sync_summary=sync_res)\\n        if tg_res.get(\\\"ok\\\"):\\n            logger.info(\\\"Daily BUY WATCH Telegram alert sent successfully!\\\")\\n        elif tg_res.get(\\\"skipped\\\"):\\n            logger.info(f\\\"Telegram alert skipped: {tg_res.get('reason')}\\\")\\n        else:\\n            logger.warning(f\\\"Telegram alert failed: {tg_res.get('error')}\\\")\\n\\n    return {\\n        \\\"sync\\\": sync_res,\\n        \\\"pipeline\\\": pipe_res,\\n        \\\"csv_export\\\": str(csv_path) if csv_path else None,\\n        \\\"telegram\\\": tg_res,\\n    }\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    parser = argparse.ArgumentParser(description=\\\"TradePilot NSE End-of-Day Sync, Screener & Telegram Notifier\\\")\\n    parser.add_argument(\\\"--force\\\", action=\\\"store_true\\\", help=\\\"Force full OHLCV download even if latest bar is cached\\\")\\n    parser.add_argument(\\\"--no-telegram\\\", action=\\\"store_true\\\", help=\\\"Skip sending Telegram notification\\\")\\n    args = parser.parse_args()\\n\\n    run_eod_job(force_refresh=args.force, send_telegram=not args.no_telegram)\\n\", \"dashboard/settings_page.py\": \"\\\"\\\"\\\"\\nPage 7: Custom Settings, NSE Stock Universe & Telegram Alert Manager.\\nAllows users to configure trading horizon, minimum score, liquidity thresholds, 100-point category weights,\\nadd/remove custom NSE stock tickers, and configure/test daily Telegram BUY WATCH notifications.\\n\\\"\\\"\\\"\\nimport streamlit as st\\nimport pandas as pd\\nfrom data.database import DatabaseManager\\nfrom analysis.pipeline import run_full_screening_pipeline\\nfrom utils.telegram_notifier import (\\n    resolve_telegram_credentials,\\n    format_eod_telegram_message,\\n    send_telegram_message,\\n    dispatch_eod_telegram_alert,\\n)\\n\\n\\ndef render_settings_page(db: DatabaseManager) -> None:\\n    st.title(\\\"\\u2699\\ufe0f Custom Screening Settings, Universe & Telegram Alerts\\\")\\n\\n    tab_cfg, tab_weights, tab_univ, tab_tg = st.tabs(\\n        [\\n            \\\"\\ud83c\\udf9b\\ufe0f Screening Thresholds\\\",\\n            \\\"\\u2696\\ufe0f 100-Point Scoring Weights\\\",\\n            \\\"\\ud83c\\udfe2 Manage NSE Stock Universe\\\",\\n            \\\"\\ud83d\\udcf2 Telegram EOD Alerts\\\",\\n        ]\\n    )\\n\\n    with tab_cfg:\\n        st.subheader(\\\"Short-Term Screening Parameters\\\")\\n        with st.form(\\\"screener_settings_form\\\"):\\n            c1, c2 = st.columns(2)\\n            with c1:\\n                horizon_opts = [\\\"3-5 Days\\\", \\\"1-2 Weeks\\\", \\\"2-6 Weeks\\\"]\\n                cur_h = db.get_setting(\\\"trading_horizon\\\", \\\"1-2 Weeks\\\")\\n                h_idx = horizon_opts.index(cur_h) if cur_h in horizon_opts else 1\\n                new_horizon = st.selectbox(\\\"Default Trading Horizon\\\", horizon_opts, index=h_idx)\\n                new_min_score = st.slider(\\\"Default Minimum Score\\\", 0.0, 90.0, float(db.get_setting(\\\"min_overall_score\\\", 60.0)), 2.5)\\n                new_min_vol = st.number_input(\\\"Minimum 20D Average Volume\\\", 10000, 5000000, int(db.get_setting(\\\"min_avg_volume_20d\\\", 150000)), 25000)\\n                new_min_rr = st.number_input(\\\"Minimum Risk/Reward Ratio\\\", 1.0, 5.0, float(db.get_setting(\\\"min_risk_reward\\\", 2.0)), 0.1)\\n            with c2:\\n                new_rsi_min = st.number_input(\\\"Minimum RSI (14)\\\", 10.0, 60.0, float(db.get_setting(\\\"rsi_min\\\", 40.0)), 1.0)\\n                new_rsi_max = st.number_input(\\\"Maximum RSI (14)\\\", 55.0, 95.0, float(db.get_setting(\\\"rsi_max\\\", 75.0)), 1.0)\\n                new_adx_min = st.number_input(\\\"Minimum ADX (14)\\\", 5.0, 40.0, float(db.get_setting(\\\"adx_min\\\", 18.0)), 1.0)\\n                all_strats = [\\n                    \\\"Strategy A: Momentum Breakout\\\",\\n                    \\\"Strategy B: Trend-Following\\\",\\n                    \\\"Strategy C: Pullback Entry\\\",\\n                    \\\"Strategy D: Early Momentum\\\",\\n                ]\\n                cur_strats = db.get_setting(\\\"enabled_strategies\\\", all_strats)\\n                new_strats = st.multiselect(\\\"Enabled Screening Strategies\\\", all_strats, default=cur_strats)\\n\\n            if st.form_submit_button(\\\"\\ud83d\\udcbe Save Settings & Re-Run Screener\\\"):\\n                db.save_setting(\\\"trading_horizon\\\", new_horizon)\\n                db.save_setting(\\\"min_overall_score\\\", new_min_score)\\n                db.save_setting(\\\"min_avg_volume_20d\\\", new_min_vol)\\n                db.save_setting(\\\"min_risk_reward\\\", new_min_rr)\\n                db.save_setting(\\\"rsi_min\\\", new_rsi_min)\\n                db.save_setting(\\\"rsi_max\\\", new_rsi_max)\\n                db.save_setting(\\\"adx_min\\\", new_adx_min)\\n                db.save_setting(\\\"enabled_strategies\\\", new_strats)\\n                run_full_screening_pipeline(db)\\n                st.success(\\\"Settings saved and universe re-scored!\\\")\\n\\n    with tab_weights:\\n        st.subheader(\\\"Configure 100-Point Scoring Model Allocation\\\")\\n        cur_w = db.get_setting(\\n            \\\"scoring_weights\\\",\\n            {\\n                \\\"trend_strength\\\": 20.0,\\n                \\\"momentum\\\": 20.0,\\n                \\\"volume_confirmation\\\": 15.0,\\n                \\\"breakout_potential\\\": 15.0,\\n                \\\"fundamental_strength\\\": 15.0,\\n                \\\"risk_reward_suitability\\\": 15.0,\\n            },\\n        )\\n        with st.form(\\\"weights_form\\\"):\\n            w1, w2, w3 = st.columns(3)\\n            wt_trend = w1.number_input(\\\"Trend Strength Weight\\\", 5.0, 50.0, float(cur_w.get(\\\"trend_strength\\\", 20.0)), 1.0)\\n            wt_mom = w1.number_input(\\\"Momentum Weight\\\", 5.0, 50.0, float(cur_w.get(\\\"momentum\\\", 20.0)), 1.0)\\n            wt_vol = w2.number_input(\\\"Volume Confirmation Weight\\\", 5.0, 40.0, float(cur_w.get(\\\"volume_confirmation\\\", 15.0)), 1.0)\\n            wt_brk = w2.number_input(\\\"Breakout Potential Weight\\\", 5.0, 40.0, float(cur_w.get(\\\"breakout_potential\\\", 15.0)), 1.0)\\n            wt_fund = w3.number_input(\\\"Fundamental Strength Weight\\\", 0.0, 40.0, float(cur_w.get(\\\"fundamental_strength\\\", 15.0)), 1.0)\\n            wt_rr = w3.number_input(\\\"Risk/Reward Suitability Weight\\\", 5.0, 40.0, float(cur_w.get(\\\"risk_reward_suitability\\\", 15.0)), 1.0)\\n\\n            if st.form_submit_button(\\\"\\u2696\\ufe0f Update Scoring Weights\\\"):\\n                total_w = wt_trend + wt_mom + wt_vol + wt_brk + wt_fund + wt_rr\\n                if abs(total_w - 100.0) > 0.01:\\n                    st.warning(f\\\"Note: Your weights sum to {total_w:.1f} (Engine will automatically normalize to 100%).\\\")\\n                db.save_setting(\\n                    \\\"scoring_weights\\\",\\n                    {\\n                        \\\"trend_strength\\\": wt_trend,\\n                        \\\"momentum\\\": wt_mom,\\n                        \\\"volume_confirmation\\\": wt_vol,\\n                        \\\"breakout_potential\\\": wt_brk,\\n                        \\\"fundamental_strength\\\": wt_fund,\\n                        \\\"risk_reward_suitability\\\": wt_rr,\\n                    },\\n                )\\n                run_full_screening_pipeline(db)\\n                st.success(\\\"Scoring weights updated and rankings recalculated!\\\")\\n\\n    with tab_univ:\\n        st.subheader(\\\"Add Custom NSE Stock to Universe\\\")\\n        with st.form(\\\"add_stock_form\\\"):\\n            u1, u2, u3, u4 = st.columns(4)\\n            new_sym = u1.text_input(\\\"NSE Symbol (e.g., ZOMATO, IRCTC)\\\")\\n            new_name = u2.text_input(\\\"Company Name\\\")\\n            new_sec = u3.text_input(\\\"Sector\\\", \\\"General\\\")\\n            new_mcap = u4.selectbox(\\\"Market Cap Category\\\", [\\\"Large Cap\\\", \\\"Mid Cap\\\", \\\"Small Cap\\\"])\\n            if st.form_submit_button(\\\"\\u2795 Add Stock to Universe\\\"):\\n                if new_sym.strip() and new_name.strip():\\n                    db.add_or_update_stock(new_sym, new_name, new_sec, new_mcap, 1)\\n                    st.success(f\\\"Added {new_sym.upper()} ({new_sym.upper()}.NS) to stock master! Click Smart Sync to fetch its data.\\\")\\n                    st.rerun()\\n                else:\\n                    st.error(\\\"Please provide both NSE Symbol and Company Name.\\\")\\n\\n        st.subheader(\\\"Active NSE Stock Universe\\\")\\n        stocks_df = pd.DataFrame(db.get_active_stocks())\\n        st.dataframe(stocks_df, use_container_width=True, hide_index=True)\\n\\n    with tab_tg:\\n        st.subheader(\\\"\\ud83d\\udcf2 Automated Telegram EOD BUY WATCH Alerts\\\")\\n        st.caption(\\n            \\\"Configure your Telegram Bot Token and Chat ID below (or via `TRADEPILOT_TELEGRAM_BOT_TOKEN` and \\\"\\n            \\\"`TRADEPILOT_TELEGRAM_CHAT_ID` in `.env`) so `eod_auto_update.py` automatically sends daily BUY WATCH setups to your phone.\\\"\\n        )\\n\\n        cur_tg = resolve_telegram_credentials(db)\\n        with st.form(\\\"telegram_settings_form\\\"):\\n            t1, t2 = st.columns(2)\\n            with t1:\\n                tg_enabled = st.checkbox(\\\"Enable Automated EOD Telegram Alerts\\\", value=cur_tg[\\\"enabled\\\"])\\n                tg_token = st.text_input(\\\"Telegram Bot Token (from @BotFather)\\\", value=cur_tg[\\\"bot_token\\\"], type=\\\"password\\\")\\n                tg_chat_id = st.text_input(\\\"Telegram Chat ID (from @userinfobot or getUpdates)\\\", value=cur_tg[\\\"chat_id\\\"])\\n            with t2:\\n                tg_max = st.slider(\\\"Max BUY WATCH Setups Per Message\\\", 1, 15, int(cur_tg[\\\"max_alerts\\\"]))\\n                tg_fallback = st.checkbox(\\n                    \\\"Include top 3 HOLD WATCH candidates if 0 BUY WATCH stocks trigger\\\",\\n                    value=cur_tg[\\\"include_hold_if_empty\\\"],\\n                )\\n\\n            if st.form_submit_button(\\\"\\ud83d\\udcbe Save Telegram Alert Settings\\\"):\\n                db.save_setting(\\n                    \\\"telegram_config\\\",\\n                    {\\n                        \\\"enabled\\\": tg_enabled,\\n                        \\\"bot_token\\\": tg_token.strip(),\\n                        \\\"chat_id\\\": tg_chat_id.strip(),\\n                        \\\"max_alerts\\\": int(tg_max),\\n                        \\\"include_hold_if_empty\\\": tg_fallback,\\n                    },\\n                )\\n                st.success(\\\"Telegram configuration saved to SQLite database!\\\")\\n\\n        btn_c1, btn_c2 = st.columns(2)\\n        with btn_c1:\\n            if st.button(\\\"\\ud83d\\udce8 Send Instant EOD BUY WATCH Alert Now\\\", use_container_width=True):\\n                res = dispatch_eod_telegram_alert(db, force_send=True)\\n                if res.get(\\\"ok\\\"):\\n                    st.success(\\\"\\u2705 EOD BUY WATCH summary sent to your Telegram!\\\")\\n                else:\\n                    st.error(f\\\"\\u274c Could not send alert: {res.get('error') or res.get('reason')}\\\")\\n\\n        with btn_c2:\\n            if st.button(\\\"\\ud83d\\udc41\\ufe0f Preview Formatted Telegram Alert Message\\\", use_container_width=True):\\n                df_screen = db.get_all_screening_results()\\n                preview_html = format_eod_telegram_message(\\n                    df_screen,\\n                    max_alerts=cur_tg[\\\"max_alerts\\\"],\\n                    include_hold_if_empty=cur_tg[\\\"include_hold_if_empty\\\"],\\n                )\\n                st.code(preview_html, language=\\\"html\\\")\\n\", \".env.example\": \"# TradePilot NSE Environment Configuration\\n# Copy this file to `.env` if you want to override defaults, configure Telegram alerts, or add paid broker API keys.\\n\\nTRADEPILOT_DATA_PROVIDER=yfinance\\nTRADEPILOT_HISTORY_YEARS=2\\nTRADEPILOT_DB_PATH=data_store/tradepilot_nse.db\\n\\n# Optional Telegram Bot EOD Alert Credentials (from @BotFather and @userinfobot)\\nTRADEPILOT_TELEGRAM_BOT_TOKEN=\\nTRADEPILOT_TELEGRAM_CHAT_ID=\\n\\n# Optional Paid Broker / Data Provider Credentials (Zerodha Kite / Upstox / TrueData)\\nTRADEPILOT_API_KEY=\\nTRADEPILOT_API_SECRET=\\n\", \"tests/test_core.py\": \"\\\"\\\"\\\"\\nAutomated Unit & Integration Test Suite for TradePilot NSE.\\nValidates:\\n1. Technical Indicator math (EMA, SMA, RSI, MACD, StochRSI, ROC, ADX, Supertrend, ATR, Bollinger, OBV, RVol).\\n2. Fundamental evaluation & missing-data normalization (distinguishing None from negative performance).\\n3. Screening Strategies A, B, C, and D detection.\\n4. 100-Point Scoring Engine & Entry/Stop-Loss/Target calculations.\\n5. Position-Sizing & Portfolio Risk Management constraints.\\n6. Event-Driven Backtesting Engine (zero look-ahead bias, transaction costs, benchmark comparison).\\n7. SQLite Database initialization, CRUD operations, and Watchlist/Portfolio lifecycle.\\n8. Telegram EOD Alert HTML formatting & credential resolution.\\n\\\"\\\"\\\"\\nimport tempfile\\nfrom pathlib import Path\\nimport numpy as np\\nimport pandas as pd\\n\\nfrom data.database import DatabaseManager\\nfrom analysis.indicators import calculate_all_indicators, extract_latest_indicator_snapshot\\nfrom analysis.fundamental import evaluate_fundamentals\\nfrom analysis.strategies import evaluate_strategies_on_bar\\nfrom analysis.scoring import calculate_entry_sl_targets, score_and_evaluate_stock\\nfrom analysis.risk_management import calculate_position_size\\nfrom analysis.backtesting import run_strategy_backtest\\nfrom utils.telegram_notifier import format_eod_telegram_message, resolve_telegram_credentials\\n\\n\\ndef _build_test_ohlcv(num_days: int = 260) -> pd.DataFrame:\\n    \\\"\\\"\\\"Builds a deterministic upward-trending OHLCV series ONLY for unit testing math validation.\\\"\\\"\\\"\\n    dates = pd.bdate_range(\\\"2025-01-01\\\", periods=num_days)\\n    np.random.seed(42)\\n    base = 1000.0 + np.linspace(0, 350, num_days) + np.sin(np.linspace(0, 12, num_days)) * 18.0\\n    close = base + np.random.normal(0, 3.5, num_days)\\n    # Force strong breakout on final bar\\n    close[-1] = max(close[-25:-1]) * 1.018\\n    open_p = close - np.random.uniform(-4.0, 6.0, num_days)\\n    open_p[-1] = close[-2] * 1.002\\n    high = np.maximum(open_p, close) + np.random.uniform(2.0, 10.0, num_days)\\n    low = np.minimum(open_p, close) - np.random.uniform(2.0, 10.0, num_days)\\n    volume = np.random.randint(200_000, 350_000, size=num_days)\\n    volume[-1] = 680_000  # High relative volume (> 1.5x)\\n\\n    return pd.DataFrame(\\n        {\\n            \\\"trade_date\\\": [d.strftime(\\\"%Y-%m-%d\\\") for d in dates],\\n            \\\"open\\\": open_p,\\n            \\\"high\\\": high,\\n            \\\"low\\\": low,\\n            \\\"close\\\": close,\\n            \\\"adj_close\\\": close,\\n            \\\"volume\\\": volume,\\n            \\\"prev_close\\\": pd.Series(close).shift(1),\\n            \\\"daily_pct_change\\\": pd.Series(close).pct_change() * 100.0,\\n        }\\n    )\\n\\n\\ndef test_technical_indicators():\\n    df = _build_test_ohlcv(260)\\n    enriched = calculate_all_indicators(df)\\n    assert not enriched.empty\\n    required_cols = [\\n        \\\"ema_9\\\",\\n        \\\"ema_20\\\",\\n        \\\"ema_50\\\",\\n        \\\"ema_100\\\",\\n        \\\"ema_200\\\",\\n        \\\"sma_20\\\",\\n        \\\"sma_50\\\",\\n        \\\"sma_200\\\",\\n        \\\"adx_14\\\",\\n        \\\"supertrend\\\",\\n        \\\"rsi_14\\\",\\n        \\\"macd\\\",\\n        \\\"macd_signal\\\",\\n        \\\"macd_hist\\\",\\n        \\\"stoch_rsi_k\\\",\\n        \\\"roc_12\\\",\\n        \\\"atr_14\\\",\\n        \\\"bb_upper\\\",\\n        \\\"bb_lower\\\",\\n        \\\"hist_volatility_20d\\\",\\n        \\\"vol_sma_20\\\",\\n        \\\"relative_volume\\\",\\n        \\\"obv\\\",\\n        \\\"vol_breakout\\\",\\n    ]\\n    for col in required_cols:\\n        assert col in enriched.columns, f\\\"Missing indicator column: {col}\\\"\\n\\n    snap = extract_latest_indicator_snapshot(\\\"TESTSYM\\\", enriched)\\n    assert snap is not None\\n    assert 0.0 <= snap[\\\"rsi_14\\\"] <= 100.0\\n    assert snap[\\\"atr_14\\\"] > 0.0\\n    assert snap[\\\"relative_volume\\\"] > 1.5\\n\\n\\ndef test_fundamentals_missing_vs_negative():\\n    strong = evaluate_fundamentals(\\n        \\\"TCS\\\",\\n        {\\n            \\\"revenue_growth_pct\\\": 16.5,\\n            \\\"profit_growth_pct\\\": 19.2,\\n            \\\"roe_pct\\\": 38.0,\\n            \\\"debt_to_equity\\\": 0.12,\\n            \\\"pe_ratio\\\": 26.5,\\n            \\\"promoter_pledging_pct\\\": None,\\n        },\\n    )\\n    assert strong[\\\"fundamental_class\\\"] == \\\"Strong Fundamentals\\\"\\n    assert strong[\\\"fundamental_raw_score\\\"] >= 70.0\\n    assert \\\"Promoter Pledging\\\" in strong[\\\"notes\\\"]\\n\\n    empty = evaluate_fundamentals(\\\"UNKNOWN\\\", {})\\n    assert empty[\\\"fundamental_class\\\"] == \\\"Data Unavailable\\\"\\n    assert empty[\\\"fundamental_raw_score\\\"] is None\\n\\n\\ndef test_scoring_and_entry_sl_targets():\\n    df = _build_test_ohlcv(260)\\n    enriched = calculate_all_indicators(df)\\n    fund = evaluate_fundamentals(\\n        \\\"HAL\\\",\\n        {\\\"revenue_growth_pct\\\": 18.0, \\\"profit_growth_pct\\\": 22.0, \\\"roe_pct\\\": 24.0, \\\"debt_to_equity\\\": 0.05, \\\"pe_ratio\\\": 25.0},\\n    )\\n    scored = score_and_evaluate_stock(\\\"HAL\\\", enriched, fund)\\n    assert scored is not None\\n    assert 0.0 <= scored[\\\"overall_score\\\"] <= 100.0\\n    assert scored[\\\"stop_loss\\\"] < scored[\\\"close_price\\\"]\\n    assert scored[\\\"target_1\\\"] > scored[\\\"close_price\\\"]\\n    assert scored[\\\"target_2\\\"] > scored[\\\"target_1\\\"]\\n    assert scored[\\\"target_3\\\"] > scored[\\\"target_2\\\"]\\n    assert scored[\\\"risk_reward_ratio\\\"] > 1.5\\n\\n\\ndef test_risk_management_position_sizing():\\n    res = calculate_position_size(\\n        total_capital=200_000.0,\\n        risk_pct_per_trade=1.0,\\n        entry_price=1000.0,\\n        stop_loss_price=950.0,\\n        target_price=1125.0,\\n    )\\n    assert \\\"error\\\" not in res\\n    assert res[\\\"max_acceptable_loss\\\"] == 2000.0\\n    assert res[\\\"risk_per_share\\\"] == 50.0\\n    assert res[\\\"quantity\\\"] == 40\\n    assert res[\\\"total_investment\\\"] == 40_000.0\\n    assert res[\\\"potential_loss\\\"] == 2000.0\\n    assert res[\\\"potential_profit\\\"] == 5000.0\\n    assert res[\\\"risk_reward_ratio\\\"] == 2.5\\n\\n\\ndef test_database_and_backtesting_lifecycle():\\n    with tempfile.TemporaryDirectory() as tmpdir:\\n        db_file = Path(tmpdir) / \\\"test_tradepilot.db\\\"\\n        db = DatabaseManager(db_path=db_file)\\n        stocks = db.get_active_stocks()\\n        assert len(stocks) >= 30\\n\\n        df = _build_test_ohlcv(260)\\n        yf_df = pd.DataFrame(\\n            {\\n                \\\"Open\\\": df[\\\"open\\\"].values,\\n                \\\"High\\\": df[\\\"high\\\"].values,\\n                \\\"Low\\\": df[\\\"low\\\"].values,\\n                \\\"Close\\\": df[\\\"close\\\"].values,\\n                \\\"Adj Close\\\": df[\\\"adj_close\\\"].values,\\n                \\\"Volume\\\": df[\\\"volume\\\"].values,\\n            },\\n            index=pd.to_datetime(df[\\\"trade_date\\\"]),\\n        )\\n        saved_count = db.save_historical_prices(\\\"RELIANCE\\\", yf_df)\\n        assert saved_count == 260\\n\\n        loaded = db.get_historical_prices(\\\"RELIANCE\\\", limit_days=300)\\n        assert len(loaded) == 260\\n\\n        db.add_to_watchlist(\\\"RELIANCE\\\", 1250.0, 1200.0, 1375.0, \\\"Strategy A\\\", \\\"Test note\\\")\\n        wl = db.get_watchlist()\\n        assert len(wl) == 1\\n\\n        db.add_portfolio_position(\\\"RELIANCE\\\", \\\"2025-10-01\\\", 1250.0, 10, 1200.0, 1375.0, \\\"Strategy A\\\", \\\"Paper trade\\\")\\n        open_pos = db.get_open_positions()\\n        assert len(open_pos) == 1\\n        pid = int(open_pos.iloc[0][\\\"position_id\\\"])\\n\\n        db.close_portfolio_position(pid, \\\"2025-10-12\\\", 1350.0, \\\"Target Reached\\\")\\n        assert len(db.get_open_positions()) == 0\\n        hist = db.get_trade_history()\\n        assert len(hist) == 1\\n        assert hist.iloc[0][\\\"gross_pnl\\\"] == 1000.0\\n\\n        bt = run_strategy_backtest(\\n            stock_histories={\\\"RELIANCE\\\": loaded},\\n            strategy_name=\\\"Strategy B: Trend-Following\\\",\\n            start_date=\\\"2025-02-01\\\",\\n            end_date=\\\"2025-12-31\\\",\\n            initial_capital=100_000.0,\\n        )\\n        assert \\\"total_trades\\\" in bt\\n        assert \\\"win_rate_pct\\\" in bt\\n\\n\\ndef test_telegram_eod_formatter():\\n    df = _build_test_ohlcv(260)\\n    enriched = calculate_all_indicators(df)\\n    fund = evaluate_fundamentals(\\n        \\\"RELIANCE\\\",\\n        {\\\"revenue_growth_pct\\\": 18.0, \\\"profit_growth_pct\\\": 22.0, \\\"roe_pct\\\": 24.0, \\\"debt_to_equity\\\": 0.05, \\\"pe_ratio\\\": 25.0},\\n    )\\n    scored = score_and_evaluate_stock(\\\"RELIANCE\\\", enriched, fund)\\n    scored[\\\"signal\\\"] = \\\"BUY WATCH\\\"\\n    screen_df = pd.DataFrame([scored])\\n\\n    msg = format_eod_telegram_message(screen_df, max_alerts=5)\\n    assert \\\"TradePilot NSE \\u2014 Daily EOD Report\\\" in msg\\n    assert \\\"#RELIANCE\\\" in msg\\n    assert \\\"Entry Zone:\\\" in msg\\n    assert \\\"Stop-Loss:\\\" in msg\\n\"}")

def apply_update():
    base_dir = Path(__file__).resolve().parent
    if not (base_dir / "app.py").exists():
        print("[ERROR] Please place apply_telegram_update.py inside your main TradePilot_NSE folder (where app.py is located).")
        return

    for rel_path, content in PATCH_FILES.items():
        target = base_dir / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        print(f"  [UPDATED] {rel_path}")

    print("\n[SUCCESS] All Telegram EOD Alert files have been updated in your local folder!")
    print("Just refresh your browser (F5) at http://localhost:8501 to see the new Telegram tab in Custom Settings.")

if __name__ == "__main__":
    apply_update()